import re

from apps.vpr.models import VprProtocol, VprTaskCatalogEntry
from apps.vpr.services.catalog_import import CatalogImportStats, _row_to_payload, _upsert_payload
from apps.vpr.services.catalog_lookup import lookup_task_catalog, normalize_subject, parse_task_code

logger = logging.getLogger(__name__)

_PARENT_CODE_RE = re.compile(r"^(\d+)")


def _parent_code(task_code: str) -> str:
    code = (task_code or "").strip().replace(" ", "")
    if not code:
        return ""
    number, sub, canonical = parse_task_code(code)
    if number is not None:
        return str(number)
    match = _PARENT_CODE_RE.match(code)
    return match.group(1) if match else code


def _seed_key(subject: str, parallel: int) -> tuple[str, int]:
    return normalize_subject(subject), int(parallel)


