# Для параллелей без точного seed используем ближайший нормативный набор.
_PARALLEL_ALIASES: dict[int, int] = {
    4: 5,  # иностранный язык 4 кл. → структура 5 кл.
    6: 5,
    7: 5,
    8: 5,
    9: 5,
}
_SUBJECT_PARALLEL_OVERRIDES: dict[tuple[str, int], int] = {
    _seed_key("Информатика", 8): 7,
    _seed_key("Информатика", 10): 7,
    _seed_key("Химия", 10): 8,
    _seed_key("Русский язык", 6): 5,
}

# Предметы протоколов → ключ seed-справочника
_SUBJECT_ALIASES: dict[str, str] = {
    "английский язык": "иностранный язык",
    "немецкий язык": "иностранный язык",
    "французский язык": "иностранный язык",
}


def _canonical_subject_key(subject: str) -> str:
    norm = normalize_subject(subject)
    return _SUBJECT_ALIASES.get(norm, norm)


def _resolve_seed(subject: str, parallel: int) -> dict[str, dict] | None:
    subject_key = _canonical_subject_key(subject)
    key = (subject_key, int(parallel))
    if key in CATALOG_SEEDS:
        return CATALOG_SEEDS[key]
    # точный ключ с исходным subject-нормализатором
    exact = _seed_key(subject, parallel)
    if exact in CATALOG_SEEDS:
        return CATALOG_SEEDS[exact]
    override = _SUBJECT_PARALLEL_OVERRIDES.get(key) or _SUBJECT_PARALLEL_OVERRIDES.get(exact)
    if override is not None:
        return CATALOG_SEEDS.get((subject_key, override)) or CATALOG_SEEDS.get((exact[0], override))
    alias = _PARALLEL_ALIASES.get(parallel)
    if alias is not None:
        return CATALOG_SEEDS.get((subject_key, alias)) or CATALOG_SEEDS.get((exact[0], alias))
    return None


def _seed_for_task(subject: str, parallel: int, task_code: str) -> dict | None:
    seeds = _resolve_seed(subject, parallel)
    if not seeds:
        return None
    code = (task_code or "").strip()
    if code in seeds:
        return seeds[code]
    parent = _parent_code(code)
    if parent and parent in seeds:
        return seeds[parent]
    # Канонический код после parse (1K1 → 1К1) — берём родителя номера
    number, _sub, _canonical = parse_task_code(code)
    if number is not None and str(number) in seeds:
        return seeds[str(number)]
    return None


def ensure_protocol_catalog_entries(protocol: VprProtocol) -> int:
    """
    Создаёт/дополняет записи справочника для заданий протокола.
    Обновляет записи без темы, если seed доступен.
    """
    subject = (protocol.subject or "").strip()
    parallel = int(protocol.parallel or 0)
    year = int(protocol.academic_year or 0)
    if not subject or not parallel or not year:
        return 0

    stats = CatalogImportStats()
    for task in protocol.tasks.all().order_by("position"):
        code = (task.code or "").strip()
        if not code:
            continue
        existing = lookup_task_catalog(
            subject=subject,
            parallel=parallel,
            academic_year=year,
            task_code=code,
        )
        if existing is not None and (existing.topic or "").strip():
            continue
        seed = _seed_for_task(subject, parallel, code)
        if seed is None:
            continue
        number, sub, canonical = parse_task_code(code)
        row = {
            "academic_year": year,
            "subject": subject,
            "parallel": parallel,
            "task_number": number or int(_parent_code(code) or 0) or 1,
            "task_subnumber": sub or "",
            "task_code": canonical or code,
            "max_score": int(task.max_score or seed.get("max_score") or 1),
            "topic": seed["topic"],
            "program_section": seed["section"],
            "checked_skill": seed["skill"],
            "difficulty": seed.get("difficulty", "Б"),
            "normative_source": f"ФИОКО. Описание КИМ ВПР {subject}, {parallel} класс, {year}",
        }
        payload = _row_to_payload(row)
        if payload:
            _upsert_payload(payload, stats)
    created_or_updated = stats.created + stats.updated
    if created_or_updated:
        logger.info(
            "VPR catalog bootstrap protocol_id=%s subject=%s parallel=%s: +%s/~%s",
            protocol.pk,
            subject,
            parallel,
            stats.created,
            stats.updated,
        )
    return created_or_updated


def bootstrap_all_protocols() -> int:
    """Дополнить справочник по всем протоколам в БД."""
    total = 0
    for protocol in VprProtocol.objects.select_related("school").iterator():
        total += ensure_protocol_catalog_entries(protocol)
    return total